{
  "name": "通用摄像头",
  "name_en": "Generic Camera",
  "manufacturer": "",
  "description": "通用可见光摄像头，可用于采集实验过程中的图像帧，适合样品观察、装置对准、过程监控和基础视觉记录等实验室场景。",
  "description_en": "A general-purpose visible-light camera used to capture image frames in laboratory workflows, suitable for sample observation, instrument alignment, process monitoring, and basic visual recording.",
  "tag_hints": [
    "camera imaging",
    "visible-light imaging",
    "frame capture",
    "sample observation",
    "experiment monitoring",
    "instrument alignment",
    "USB camera"
  ],
  "actions": [
    {
      "action_name": "auto-openCVProperties",
      "description": "查看相机的可用属性",
      "description_en": "View the camera's available properties."
    },
    {
      "action_name": "auto-isCompatibleWith",
      "description": "检查设备标识信息是否与该相机兼容",
      "description_en": "Check whether the device identification information is compatible with this camera."
    },
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化并打开相机",
      "description_en": "Initialize and open the camera."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭并释放相机",
      "description_en": "Shut down and release the camera."
    },
    {
      "action_name": "auto-doCaptureFrame",
      "description": "采集单帧图像",
      "description_en": "Capture a single image frame."
    },
    {
      "action_name": "auto-availableCameras",
      "description": "列出当前可用的摄像头",
      "description_en": "List the cameras currently available."
    }
  ]
}

